import axios from "axios";
import { ADD, DELETE, EDIT, FILTER } from "../types/productTypes";
import { addProduct, deleteProduct } from "../actions/productActions";
import { Axios } from "../../axios";

const initalState = 0;

const productReducer = (state = initalState, action) => {
  switch (action.type) {
    case ADD:
      return  [...state, action.payload];
    case EDIT:
      return {};
    case DELETE:
      return [
        ...state,
        state.filter((elm) => {
          return elm.id != action.payload;
        }),
      ];

    default:
      return state;
  }
};

export const getProductsMiddleWare = () => {
  return (dispatch) => {
    axios("https://api.escuelajs.co/api/v1/products").then((res) =>
      dispatch(addProduct(res.data))
    );
  };
};

export const delProductMiddleWare = (id) => {
  return (dispatch) => {
    Axios.deleteData(id).then((res) => {
      dispatch(deleteProduct(res.data));
    });
  };
};

export { productReducer };
